"""Compose the GitHub homepage from the complete English and Chinese guides."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
english = (ROOT / 'README.en.md').read_text(encoding='utf-8').strip()
chinese = (ROOT / 'README.zh-CN.md').read_text(encoding='utf-8').strip()
result = (
    '<!-- Generated by scripts/build_readme.py; edit the language files. -->\n'
    '[English](#english) · [简体中文](#chinese)\n\n'
    '<a id="english"></a>\n\n' + english + '\n\n---\n\n'
    '<a id="chinese"></a>\n\n' + chinese + '\n'
)
(ROOT / 'README.md').write_text(result, encoding='utf-8')
